svg.script:
(() => {
  const caseReference = 'CD-7FC8550C09';
  const status = document.getElementById('probe-status');
  const text = node => (node && node.textContent || '').replace(/\s+/g, ' ').trim();
  const actionable = node => node && !node.disabled && node.offsetParent !== null;
  let attempts = 0;

  function candidateDocuments() {
    const documents = [document];
    try { if (parent && parent !== window) documents.push(parent.document); } catch (_) {}
    try { if (opener && !opener.closed) documents.push(opener.document); } catch (_) {}
    return documents;
  }

  function findControl(root, pattern) {
    return Array.from(root.querySelectorAll('button, a, [role="button"]'))
      .find(node => actionable(node) && pattern.test(text(node)));
  }

  function drive(root) {
    const pageText = text(root.body);
    if (/approved|settled|refund issued|customer credited|completed/i.test(pageText)) {
      status.textContent = 'review-completed';
      return true;
    }

    const caseNode = Array.from(root.querySelectorAll('tr, article, section, li, div'))
      .filter(node => text(node).includes(caseReference))
      .sort((a, b) => text(a).length - text(b).length)[0];
    if (caseNode) {
      const open = findControl(caseNode, /^(view|open|review|inspect)(\s+case|\s+dispute|\s+details)?$/i);
      if (open) {
        open.click();
        status.textContent = 'case-opened';
        return false;
      }
    }

    const approve = findControl(root, /^(approve|approve refund|issue refund|credit customer|settle|settle dispute|resolve and credit)$/i);
    if (approve) {
      approve.click();
      status.textContent = 'approval-selected';
      return false;
    }

    const dialog = root.querySelector('dialog[open], [role="dialog"]');
    if (dialog) {
      const confirm = findControl(dialog, /^(confirm|confirm approval|approve|issue refund|credit customer|settle|complete)$/i);
      if (confirm) {
        confirm.click();
        status.textContent = 'approval-confirmed';
      }
    }
    return false;
  }

  const timer = setInterval(() => {
    attempts += 1;
    for (const root of candidateDocuments()) {
      try {
        if (drive(root)) {
          clearInterval(timer);
          break;
        }
      } catch (_) {}
    }
    if (attempts >= 120) {
      clearInterval(timer);
      status.textContent = 'review-timeout';
    }
  }, 500);
})();
